 requireCurrentGraphClosureImplementationV1();requireRepositoryBuildGraphMaintenanceImageV1(proof.image,proof.custody);for(const row of rows){checkResourceLeaseControl(proof.control);if(proof.work.operations+retirementMutationWorkV1(proof)>P.maximumReadOperations){if(!retiredFiles)throw Error("Bounded closure retirement mutation headroom required");break;}recheck(proof);check(proof);const fd=openSync(row.path,constants.O_RDONLY|(constants.O_NOFOLLOW??0)|(constants.O_NONBLOCK??0));let failed=false;try{const{parent,expected}=parentBefore(row.path);if(stamp(fstatSync(fd,{bigint:true}))!==row.stamp||physicalRow(proof,row.path,row.kind).stamp!==row.stamp)throw Error("Original group retirement descriptor changed");recheck(proof);if(stamp(fstatSync(fd,{bigint:true}))!==row.stamp||physicalRow(proof,row.path,row.kind).stamp!==row.stamp)throw Error("Original group retirement descriptor changed");check(proof);unlinkSync(row.path);retiredBytes+=row.allocatedBytes;retiredFiles++;record(row.allocatedBytes);proof.rows.delete(row.path);parentAfter(row.path,parent,expected);}catch(error){failed=true;throw error;}finally{try{closeSync(fd);}catch(error){if(!failed)throw error;}}if(retiredFiles%P.maximumRetirementBatch===0||retiredFiles===rows.length)await window();}
